# Kings_Accounting_Suite/aureon_systems/aureon_lattice_simulation.py

from typing import List, Tuple

class LatticeNode:
    """Represents a node in the lattice."""

    def __init__(self, value: float):
        self.value = value
        self.neighbors: List['LatticeNode'] = []

    def add_neighbor(self, neighbor: 'LatticeNode'):
        if neighbor not in self.neighbors:
            self.neighbors.append(neighbor)
            neighbor.add_neighbor(self)

class LatticeSimulation:
    """
    Simulates a lattice system.

    Parameters:
    - size (int): The number of nodes along one dimension of the square lattice.
    """

    def __init__(self, size: int):
        self.size = size
        self.nodes: List[List[LatticeNode]] = [[None] * size for _ in range(size)]
        self.initialize_nodes()
        self.connect_neighbors()

    def initialize_nodes(self):
        """Initializes all nodes with random values."""
        from random import uniform
        for i in range(self.size):
            for j in range(self.size):
                self.nodes[i][j] = LatticeNode(uniform(-10, 10))

    def connect_neighbors(self):
        """Connects each node to its neighbors in the lattice."""
        for i in range(self.size):
            for j in range(self.size):
                current_node = self.nodes[i][j]
                if i > 0:
                    current_node.add_neighbor(self.nodes[i-1][j])
                if i < self.size - 1:
                    current_node.add_neighbor(self.nodes[i+1][j])
                if j > 0:
                    current_node.add_neighbor(self.nodes[i][j-1])
                if j < self.size - 1:
                    current_node.add_neighbor(self.nodes[i][j+1])

    def get_node_value(self, position: Tuple[int, int]) -> float:
        """Returns the value of the node at the given position."""
        x, y = position
        if 0 <= x < self.size and 0 <= y < self.size:
            return self.nodes[x][y].value
        else:
            raise IndexError("Position out of bounds")

    def set_node_value(self, position: Tuple[int, int], value: float):
        """Sets the value of the node at the given position."""
        x, y = position
        if 0 <= x < self.size and 0 <= y < self.size:
            self.nodes[x][y].value = value
        else:
            raise IndexError("Position out of bounds")

# Example usage:
if __name__ == "__main__":
    sim = LatticeSimulation(5)
    print(sim.get_node_value((2, 2)))
    sim.set_node_value((2, 2), 42.0)
    print(sim.get_node_value((2, 2)))
```

### Explanation:

1. **LatticeNode Class**:
   - Represents a single node in the lattice.
   - Each node has a value and a list of neighboring nodes.
   - Methods to add neighbors and retrieve/set node values.

2. **LatticeSimulation Class**:
   - Initializes a square lattice of nodes.
   - Connects each node to its neighbors.
   - Provides methods to get and set node values by their positions.

3. **Example Usage**:
   - Demonstrates creating a lattice simulation and manipulating node values.

