    last_updated = dashboard.get_data("last_updated")
    transactions = dashboard.get_data("transactions")

    print(f"Balance: ${balance}")
    print(f"Last Updated: {last_updated}")
    print("Transactions:")
    for transaction in transactions:
        print(transaction)

