# aureon/plumber/authorization_chain_v02.py

from typing import List, Optional

class AuthorizationChain:
    def __init__(self):
        self.authorizers: List[Authorizer] = []

    def add_authorizer(self, authorizer: 'Authorizer') -> None:
        """Add an authorizer to the chain."""
        self.authorizers.append(authorizer)

    def authorize(self, user: 'User', action: str) -> bool:
        """Authorize a user for a specific action using the chain of authorizers."""
        for authorizer in self.authorizers:
            if not authorizer.can_authorize(user, action):
                return False
        return True


class Authorizer:
    def can_authorize(self, user: 'User', action: str) -> bool:
        """Determine if the user can perform the given action."""
        raise NotImplementedError("Subclasses must implement this method")


class RoleBasedAuthorizer(Authorizer):
    def __init__(self, roles: List[str]):
        self.roles = roles

    def can_authorize(self, user: 'User', action: str) -> bool:
        """Check if the user has any of the required roles to perform the action."""
        return any(role in user.roles for role in self.roles)


class PermissionBasedAuthorizer(Authorizer):
    def __init__(self, permissions: List[str]):
        self.permissions = permissions

    def can_authorize(self, user: 'User', action: str) -> bool:
        """Check if the user has any of the required permissions to perform the action."""
        return any(permission in user.permissions for permission in self.permissions)


class User:
    def __init__(self, username: str, roles: List[str], permissions: List[str]):
        self.username = username
        self.roles = roles
        self.permissions = permissions


# Example usage
if __name__ == "__main__":
    # Create users
    admin_user = User(username="admin", roles=["admin"], permissions=["read", "write"])
    regular_user = User(username="user", roles=["user"], permissions=["read"])

    # Create authorizers
    role_based_auth = RoleBasedAuthorizer(roles=["admin"])
    permission_based_auth = PermissionBasedAuthorizer(permissions=["write"])

    # Create authorization chain
    auth_chain = AuthorizationChain()
    auth_chain.add_authorizer(role_based_auth)
    auth_chain.add_authorizer(permission_based_auth)

    # Check authorization
    print(auth_chain.authorize(admin_user, "write"))  # Should be True
    print(auth_chain.authorize(regular_user, "write"))  # Should be False
```

