from typing import List, Optional

class AuthorizationContext:
    def __init__(self, user_id: str, permissions: List[str]):
        self.user_id = user_id
        self.permissions = permissions

class AuthorizationRule:
    def __init__(self, required_permissions: List[str]):
        self.required_permissions = required_permissions

    def is_allowed(self, context: AuthorizationContext) -> bool:
        return all(permission in context.permissions for permission in self.required_permissions)

class AuthorizationChain:
    def __init__(self):
        self.rules: List[AuthorizationRule] = []

    def add_rule(self, rule: AuthorizationRule):
        self.rules.append(rule)

    def authorize(self, context: AuthorizationContext) -> bool:
        for rule in self.rules:
            if not rule.is_allowed(context):
                return False
        return True

def create_default_authorization_chain() -> AuthorizationChain:
    chain = AuthorizationChain()

    # Example rules
    read_rule = AuthorizationRule(["read"])
    write_rule = AuthorizationRule(["write"])

    chain.add_rule(read_rule)
    chain.add_rule(write_rule)

    return chain

# Example usage
if __name__ == "__main__":
    context = AuthorizationContext(user_id="user123", permissions=["read", "write"])
    default_chain = create_default_authorization_chain()

    if default_chain.authorize(context):
        print("Access granted.")
    else:
        print("Access denied.")
