from typing import List, Dict

class Portfolio:
    def __init__(self):
        self.positions = {}

    def add_position(self, symbol: str, quantity: float, price: float):
        if symbol not in self.positions:
            self.positions[symbol] = {'quantity': 0, 'average_price': 0}
        total_cost = self.positions[symbol]['quantity'] * self.positions[symbol]['average_price']
        new_total_cost = total_cost + (quantity * price)
        new_quantity = self.positions[symbol]['quantity'] + quantity
        self.positions[symbol]['average_price'] = new_total_cost / new_quantity

    def get_value(self) -> float:
        return sum(quantity * price for symbol, data in self.positions.items() for price in [data['average_price']] * int(data['quantity']))

def run_billion_trader(portfolio: Portfolio, trades: List[Dict[str, float]]) -> None:
    """
    Runs a trading strategy on a given portfolio based on a list of trades.

    Parameters:
    - portfolio: An instance of the Portfolio class representing the current state of the portfolio.
    - trades: A list of dictionaries where each dictionary represents a trade with keys 'symbol', 'quantity', and 'price'.

    Returns:
    None
    """
    for trade in trades:
        symbol = trade['symbol']
        quantity = trade['quantity']
        price = trade['price']

        if quantity > 0:
            # Buy order
            portfolio.add_position(symbol, quantity, price)
        else:
            # Sell order
            if symbol in portfolio.positions and abs(quantity) <= portfolio.positions[symbol]['quantity']:
                portfolio.add_position(symbol, quantity, price)
            else:
                raise ValueError(f"Insufficient quantity or invalid symbol for sell order: {symbol}")

    print(f"Final portfolio value: ${portfolio.get_value():,.2f}")

