class QuantumWarfareEngine:
    def __init__(self, num_ships: int):
        self.num_ships = num_ships
        self.ships = [Ship(f"Ship-{i+1}") for i in range(num_ships)]
        self.battlefield = [[None] * 10 for _ in range(10)]

    def deploy_ships(self) -> None:
        """Randomly deploy ships on the battlefield."""
        for ship in self.ships:
            while True:
                x = random.randint(0, 9)
                y = random.randint(0, 9)
                if self.battlefield[x][y] is None:
                    self.battlefield[x][y] = ship
                    break

    def attack(self, target_x: int, target_y: int) -> bool:
        """Attack the specified coordinates on the battlefield."""
        if 0 <= target_x < 10 and 0 <= target_y < 10:
            if self.battlefield[target_x][target_y] is not None:
                self.battlefield[target_x][target_y].take_damage()
                return True
        return False

    def check_game_over(self) -> bool:
        """Check if all ships have been destroyed."""
        for row in self.battlefield:
            for cell in row:
                if cell is not None and not cell.is_destroyed():
                    return False
        return True


