        self.name = name
        self.health = 100

    def take_damage(self) -> None:
        """Reduce the ship's health by a random amount."""
        damage = random.randint(10, 30)
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def is_destroyed(self) -> bool:
        """Check if the ship is destroyed."""
        return self.health == 0


