        """Remove an entity from the world by its ID."""
        self.entities = [entity for entity in self.entities if entity['id'] != entity_id]

    def move_entity(self, entity_id: str, new_position: Dict[str, int]):
        """Move an entity to a new position."""
        for entity in self.entities:
            if entity['id'] == entity_id:
                entity['position'] = new_position
                break
        else:
            raise KeyError(f"Entity with ID {entity_id} not found.")

    def get_entities_in_range(self, position: Dict[str, int], radius: int) -> List[Dict[str, Any]]:
        """Get entities within a certain range from a given position."""
        return [
            entity for entity in self.entities
            if abs(entity['position']['x'] - position['x']) <= radius and
               abs(entity['position']['y'] - position['y']) <= radius
        ]

    def simulate_step(self):
        """Simulate one step of the world, e.g., moving entities randomly."""
