from typing import Dict, List, Optional

class MetacognitiveAgent:
    def __init__(self):
        self.knowledge_base: Dict[str, str] = {}
        self.memory: List[str] = []

    def learn(self, data: str) -> None:
        """Learn new information by adding it to the knowledge base."""
        self.knowledge_base[data.split()[0]] = ' '.join(data.split()[1:])

    def recall(self, key: str) -> Optional[str]:
        """Recall information based on a key."""
        return self.knowledge_base.get(key)

    def store_memory(self, item: str) -> None:
        """Store an item in memory."""
        self.memory.append(item)

    def retrieve_memory(self) -> List[str]:
        """Retrieve all stored memories."""
        return self.memory

class AurisMetacognition(MetacognitiveAgent):
    def __init__(self):
        super().__init__()
        self.decision_tree: Dict[str, List[str]] = {}

    def train_decision_tree(self, input_data: str, output: str) -> None:
        """Train the decision tree with new input and output pairs."""
        if input_data not in self.decision_tree:
            self.decision_tree[input_data] = [output]
        else:
            self.decision_tree[input_data].append(output)

    def make_decision(self, input_data: str) -> Optional[str]:
        """Make a decision based on the trained decision tree."""
        if input_data in self.decision_tree:
            return self.decision_tree[input_data][0]  # For simplicity, returning the first output
        return None

    def evaluate_performance(self) -> float:
        """Evaluate the performance of the decision tree."""
        total_correct = 0
        total_tests = 0

        for input_data, outputs in self.decision_tree.items():
            correct_output = outputs[0]  # Assuming the first output is the correct one
            user_input = input(f"Test input: {input_data}, Expected output: {correct_output}. Enter your prediction: ")
            if user_input == correct_output:
                total_correct += 1
            total_tests += 1

        return total_correct / total_tests if total_tests > 0 else 0.0

# Example usage
if __name__ == "__main__":
    auris = AurisMetacognition()
    auris.train_decision_tree("What is the capital of France?", "Paris")
    auris.train_decision_tree("Who wrote 'To Kill a Mockingbird'?", "Harper Lee")

    print(auris.make_decision("What is the capital of France?"))  # Should print "Paris"
    print(auris.make_decision("Who wrote 'To Kill a Mockingbird'?"))  # Should print "Harper Lee"

    print("Performance evaluation:", auris.evaluate_performance())
```

