"""
Guerrilla Warfare Engine

This module provides the core functionality for simulating guerrilla warfare scenarios.
It includes classes and functions to manage units, terrain, and combat operations.

Classes:
    - Unit: Represents an individual unit in the simulation.
    - Terrain: Represents the geographical features of the battlefield.
    - Battle: Manages the execution of battles between opposing forces.

Functions:
    - initialize_units: Initializes a list of units with given attributes.
    - generate_terrain: Creates a terrain object based on specified parameters.
    - simulate_battle: Executes a battle simulation between two sets of units.
"""

from typing import List, Dict, Tuple

class Unit:
    """Represents an individual unit in the simulation."""

    def __init__(self, name: str, health: int, attack_power: int):
        self.name = name
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, damage: int) -> None:
        """Reduces the unit's health by the specified amount."""
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def is_alive(self) -> bool:
        """Returns True if the unit is still alive, False otherwise."""
        return self.health > 0

class Terrain:
    """Represents the geographical features of the battlefield."""

    def __init__(self, features: Dict[str, float]):
        self.features = features  # e.g., {'forest': 0.8, 'mountain': 0.5}

    def get_feature_modifier(self, feature_type: str) -> float:
        """Returns the modifier for the specified terrain feature."""
        return self.features.get(feature_type, 1.0)

class Battle:
    """Manages the execution of battles between opposing forces."""

    def __init__(self, units_a: List[Unit], units_b: List[Unit], terrain: Terrain):
        self.units_a = units_a
        self.units_b = units_b
        self.terrain = terrain

    def execute(self) -> Tuple[List[Unit], List[Unit]]:
        """Executes the battle and returns the remaining units for each side."""
        while self.units_a and self.units_b:
            # Simulate attacks between units from both sides
            for unit_a in self.units_a[:]:
                target_b = self.units_b.pop(0)
                unit_a.take_damage(target_b.attack_power * self.terrain.get_feature_modifier('urban'))
                if not target_b.is_alive():
                    self.units_b.append(target_b)

            for unit_b in self.units_b[:]:
                target_a = self.units_a.pop(0)
                unit_b.take_damage(target_a.attack_power * self.terrain.get_feature_modifier('rural'))
                if not target_a.is_alive():
                    self.units_a.append(target_a)

        return self.units_a, self.units_b

def initialize_units(names: List[str], healths: List[int], attack_powers: List[int]) -> List[Unit]:
    """Initializes a list of units with given attributes."""
    return [Unit(name, health, attack_power) for name, health, attack_power in zip(names, healths, attack_powers)]

def generate_terrain(features: Dict[str, float]) -> Terrain:
    """Creates a terrain object based on specified parameters."""
    return Terrain(features)

def simulate_battle(units_a: List[Unit], units_b: List[Unit], terrain: Terrain) -> Tuple[List[Unit], List[Unit]]:
    """Executes a battle simulation between two sets of units."""
    battle = Battle(units_a, units_b, terrain)
    return battle.execute()
```

