class GuerrillaUnit:
    def __init__(self, unit_id: int, location: str):
        self.unit_id = unit_id
        self.location = location

    def move_to(self, new_location: str) -> None:
        """Move the unit to a new location."""
        self.location = new_location

class GuerrillaWarfareEngine:
    def __init__(self):
        self.units: Dict[int, GuerrillaUnit] = {}

    def add_unit(self, unit: GuerrillaUnit) -> None:
        """Add a new guerrilla unit to the engine."""
        if unit.unit_id in self.units:
            raise ValueError(f"Unit ID {unit.unit_id} already exists.")
        self.units[unit.unit_id] = unit

    def remove_unit(self, unit_id: int) -> None:
        """Remove a guerrilla unit from the engine by its ID."""
        if unit_id not in self.units:
            raise KeyError(f"Unit ID {unit_id} does not exist.")
        del self.units[unit_id]

    def get_unit(self, unit_id: int) -> Optional[GuerrillaUnit]:
        """Get a guerrilla unit by its ID."""
        return self.units.get(unit_id)

    def move_units(self, moves: List[Tuple[int, str]]) -> None:
        """Move multiple units to new locations based on a list of tuples (unit_id, new_location)."""
        for unit_id, new_location in moves:
            if unit_id not in self.units:
                raise KeyError(f"Unit ID {unit_id} does not exist.")
            self.units[unit_id].move_to(new_location)

