        self.location = new_location

class GuerrillaOperation:
    def __init__(self, operation_id: int, units: List[GuerrillaUnit]):
        self.operation_id = operation_id
        self.units = units

    def add_unit(self, unit: GuerrillaUnit) -> None:
        """Add a unit to the operation."""
        self.units.append(unit)

    def remove_unit(self, unit_id: int) -> None:
        """Remove a unit from the operation by ID."""
        self.units = [unit for unit in self.units if unit.unit_id != unit_id]

class GuerrillaWarfareEngine:
    def __init__(self):
        self.operations: Dict[int, GuerrillaOperation] = {}

    def create_operation(self, operation_id: int) -> None:
        """Create a new guerrilla operation."""
        if operation_id not in self.operations:
            self.operations[operation_id] = GuerrillaOperation(operation_id, [])

    def get_operation(self, operation_id: int) -> Optional[GuerrillaOperation]:
        """Get an operation by its ID."""
        return self.operations.get(operation_id)

    def add_unit_to_operation(self, operation_id: int, unit: GuerrillaUnit) -> None:
        """Add a unit to a specific operation."""
        operation = self.get_operation(operation_id)
        if operation:
            operation.add_unit(unit)

    def remove_unit_from_operation(self, operation_id: int, unit_id: int) -> None:
        """Remove a unit from a specific operation by ID."""
        operation = self.get_operation(operation_id)
        if operation:
            operation.remove_unit(unit_id)

    def move_unit_in_operation(self, operation_id: int, unit_id: int, new_location: str) -> None:
        """Move a unit within a specific operation to a new location."""
        operation = self.get_operation(operation_id)
        if operation:
            for unit in operation.units:
                if unit.unit_id == unit_id:
                    unit.move_to(new_location)
                    break

