import React, { useState } from 'react';
import styled from 'styled-components';

interface ResizableProps {
  children: React.ReactNode;
  initialWidth?: number;
}

const Resizer = styled.div`
  position: absolute;
  right: -5px;
  top: 0;
  bottom: 0;
  width: 10px;
  cursor: ew-resize;
`;

const ResizableContainer = styled.div<{ width: number }>`
  display: flex;
  position: relative;
  width: ${({ width }) => `${width}px`};
`;

const Resizable: React.FC<ResizableProps> = ({ children, initialWidth = 300 }) => {
  const [width, setWidth] = useState(initialWidth);

  const handleResize = (e: React.MouseEvent) => {
    e.preventDefault();
    const mouseMoveHandler = (moveEvent: MouseEvent) => {
      setWidth((prevWidth) => prevWidth + moveEvent.movementX);
    };

    const mouseUpHandler = () => {
      document.removeEventListener('mousemove', mouseMoveHandler);
      document.removeEventListener('mouseup', mouseUpHandler);
    };

    document.addEventListener('mousemove', mouseMoveHandler);
    document.addEventListener('mouseup', mouseUpHandler);
  };

  return (
    <ResizableContainer width={width}>
      {children}
      <Resizer onMouseDown={handleResize} />
    </ResizableContainer>
  );
};

export default Resizable;
```

This TypeScript component `Resizable` allows its child elements to be resized horizontally by dragging a resizer bar on the right side of the container. The component uses styled-components for styling and manages the width state using React hooks. The `initialWidth` prop can be used to set the initial width of the resizable container.

