from typing import List, Dict, Optional
import requests

class LiveTVStation:
    def __init__(self, station_id: str, name: str, url: str):
        self.station_id = station_id
        self.name = name
        self.url = url

    def get_stream_info(self) -> Dict[str, Optional[str]]:
        try:
            response = requests.get(f"{self.url}/info")
            if response.status_code == 200:
                return response.json()
            else:
                return {"error": f"Failed to fetch stream info (Status Code: {response.status_code})"}
        except requests.RequestException as e:
            return {"error": str(e)}

def fetch_live_tv_stations() -> List[LiveTVStation]:
    """
    Fetches a list of live TV stations from a predefined API endpoint.

    Returns:
        List[LiveTVStation]: A list of LiveTVStation objects representing available stations.
    """
    api_url = "https://api.example.com/live-tv-stations"
    try:
        response = requests.get(api_url)
        if response.status_code == 200:
            stations_data = response.json()
            stations = [
                LiveTVStation(station['id'], station['name'], station['url'])
                for station in stations_data
            ]
            return stations
        else:
            print(f"Failed to fetch live TV stations (Status Code: {response.status_code})")
            return []
    except requests.RequestException as e:
        print(f"An error occurred while fetching live TV stations: {e}")
        return []

def main():
    stations = fetch_live_tv_stations()
    for station in stations:
        print(f"Station ID: {station.station_id}, Name: {station.name}, URL: {station.url}")
        stream_info = station.get_stream_info()
        print(stream_info)

if __name__ == "__main__":
    main()
