# scripts/validation/generate_repo_navigation_completion_audit.py

import os
from typing import List, Dict

def get_all_files_in_directory(directory: str) -> List[str]:
    """Recursively get all files in a directory."""
    file_list = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_list.append(os.path.join(root, file))
    return file_list

def analyze_file_content(file_path: str) -> Dict[str, int]:
    """Analyze the content of a file to count occurrences of specific keywords."""
    keyword_counts = {}
    with open(file_path, 'r', encoding='utf-8') as file:
        for line in file:
            words = line.split()
            for word in words:
                if word.isidentifier():  # Check if it's a valid identifier
                    if word not in keyword_counts:
                        keyword_counts[word] = 1
                    else:
                        keyword_counts[word] += 1
    return keyword_counts

def generate_audit_report(files: List[str], output_file: str) -> None:
    """Generate an audit report based on the analysis of file contents."""
    audit_data = {}
    for file in files:
        print(f"Analyzing {file}...")
        keyword_counts = analyze_file_content(file)
        audit_data[file] = keyword_counts

    with open(output_file, 'w', encoding='utf-8') as report_file:
        for file, counts in audit_data.items():
            report_file.write(f"File: {file}\n")
            for keyword, count in sorted(counts.items(), key=lambda x: x[1], reverse=True):
                report_file.write(f"  Keyword: {keyword}, Count: {count}\n")
            report_file.write("\n")

if __name__ == "__main__":
    repo_root = "path/to/your/repo"
    output_file = "repo_navigation_completion_audit.txt"

    all_files = get_all_files_in_directory(repo_root)
    generate_audit_report(all_files, output_file)
    print(f"Audit report generated at {output_file}")
```

### Explanation:

1. **get_all_files_in_directory**: Recursively walks through the specified directory and collects all file paths.
2. **analyze_file_content**: Reads each file and counts the occurrences of valid Python identifiers (keywords).
3. **generate_audit_report**: Compiles the analysis results into a structured format and writes them to an output file.

This script provides a basic framework for generating an audit report on the usage of keywords across a repository. You can extend or modify this script to include more sophisticated analysis or reporting features as needed.

