import { NextApiRequest, NextApiResponse } from 'next';
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.SUPABASE_URL || '';
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY || '';

const supabase = createClient(supabaseUrl, supabaseAnonKey);

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  if (req.method === 'POST') {
    const { message, user_id } = req.body;

    if (!message || !user_id) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    try {
      const { data, error } = await supabase
        .from('chat_messages')
        .insert([{ message, user_id }]);

      if (error) {
        throw error;
      }

      res.status(201).json(data);
    } catch (error) {
      console.error(error);
      res.status(500).json({ error: 'Internal server error' });
    }
  } else {
    res.setHeader('Allow', ['POST']);
    res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
```

This TypeScript file defines an API endpoint for handling chat messages using Supabase. It includes type hints for the request and response objects, and uses environment variables to store the Supabase URL and anonymous key. The function checks if the HTTP method is POST and validates the incoming request body before inserting the message into the `chat_messages` table in Supabase. If successful, it returns the inserted data; otherwise, it handles errors appropriately.

