def _assert_delivery_schema_valid(delivery_data: Dict[str, Any], schema: Dict[str, Any]) -> None:
    """
    Asserts that the given delivery data conforms to the specified JSON schema.

    Args:
        delivery_data (Dict[str, Any]): The delivery data to validate.
        schema (Dict[str, Any]): The JSON schema to validate against.

    Raises:
