from typing import Dict

class UnifiedMarginTrader:
    def __init__(self, exchanges: Dict[str, Dict]):
        self.exchanges = exchanges

    def get_exchange_lot_size(self, exchange_name: str, trading_pair: str) -> float:
        """
        Retrieves the lot size for a given trading pair on a specified exchange.

        Parameters:
        - exchange_name (str): The name of the exchange.
        - trading_pair (str): The trading pair (e.g., 'BTC/USD').

        Returns:
        - float: The lot size for the trading pair on the specified exchange.

        Raises:
        - KeyError: If the exchange or trading pair is not found.
        """
        if exchange_name not in self.exchanges:
            raise KeyError(f"Exchange '{exchange_name}' not found.")

        exchange_info = self.exchanges[exchange_name]
        if trading_pair not in exchange_info['trading_pairs']:
            raise KeyError(f"Trading pair '{trading_pair}' not found on exchange '{exchange_name}'.")

        return exchange_info['trading_pairs'][trading_pair]['lot_size']

# Example usage:
exchanges_data = {
    'Binance': {
        'trading_pairs': {
            'BTC/USD': {'lot_size': 0.001},
            'ETH/USD': {'lot_size': 0.01}
        }
    },
    'Kraken': {
        'trading_pairs': {
            'XBT/USD': {'lot_size': 0.001},
            'ETH/USD': {'lot_size': 0.01}
        }
    }
}

trader = UnifiedMarginTrader(exchanges=exchanges_data)
print(trader.get_exchange_lot_size('Binance', 'BTC/USD'))  # Output: 0.001
```

