from typing import Dict, List, Optional

class UnifiedEcosystem:
    def __init__(self):
        self.traders: Dict[str, 'Trader'] = {}
        self.markets: Dict[str, 'Market'] = {}

    def add_trader(self, trader_id: str, trader: 'Trader') -> None:
        """Add a trader to the ecosystem."""
        if trader_id in self.traders:
            raise ValueError(f"Trader with ID {trader_id} already exists.")
        self.traders[trader_id] = trader

    def get_trader(self, trader_id: str) -> 'Trader':
        """Retrieve a trader by their ID."""
        return self.traders.get(trader_id)

    def remove_trader(self, trader_id: str) -> None:
        """Remove a trader from the ecosystem."""
        if trader_id not in self.traders:
            raise KeyError(f"Trader with ID {trader_id} does not exist.")
        del self.traders[trader_id]

    def add_market(self, market_id: str, market: 'Market') -> None:
        """Add a market to the ecosystem."""
        if market_id in self.markets:
            raise ValueError(f"Market with ID {market_id} already exists.")
        self.markets[market_id] = market

    def get_market(self, market_id: str) -> 'Market':
        """Retrieve a market by its ID."""
        return self.markets.get(market_id)

    def remove_market(self, market_id: str) -> None:
        """Remove a market from the ecosystem."""
        if market_id not in self.markets:
            raise KeyError(f"Market with ID {market_id} does not exist.")
        del self.markets[market_id]


class Trader:
    def __init__(self, trader_id: str, name: str):
        self.trader_id = trader_id
        self.name = name
        self.positions: Dict[str, float] = {}

    def open_position(self, market_id: str, amount: float) -> None:
        """Open a position on a specific market."""
        if market_id not in self.positions:
            self.positions[market_id] = 0
        self.positions[market_id] += amount

    def close_position(self, market_id: str, amount: float) -> None:
        """Close a position on a specific market."""
        if market_id not in self.positions:
            raise KeyError(f"No position found for market ID {market_id}.")
        if self.positions[market_id] < amount:
            raise ValueError("Insufficient position size to close.")
        self.positions[market_id] -= amount


class Market:
    def __init__(self, market_id: str, base_asset: str, quote_asset: str):
        self.market_id = market_id
        self.base_asset = base_asset
        self.quote_asset = quote_asset
        self.tickers: Dict[str, float] = {}

    def update_ticker(self, ticker_id: str, price: float) -> None:
        """Update the ticker price for a specific asset."""
        self.tickers[ticker_id] = price

    def get_ticker(self, ticker_id: str) -> float:
        """Retrieve the current ticker price for a specific asset."""
        return self.tickers.get(ticker_id)
