class TradingStrategy:
    def __init__(self, name: str):
        self.name = name

    def execute(self, data: List[Dict[str, float]]) -> Optional[float]:
        raise NotImplementedError("Subclasses must implement this method")

class MovingAverageCrossover(TradingStrategy):
    def __init__(self, short_window: int, long_window: int):
        super().__init__("Moving Average Crossover")
        self.short_window = short_window
        self.long_window = long_window

    def execute(self, data: List[Dict[str, float]]) -> Optional[float]:
        if len(data) < max(self.short_window, self.long_window):
            return None

        short_mavg = sum(item['close'] for item in data[-self.short_window:]) / self.short_window
        long_mavg = sum(item['close'] for item in data[-self.long_window:]) / self.long_window

        if short_mavg > long_mavg:
            return 1.0  # Buy signal
        elif short_mavg < long_mavg:
            return -1.0  # Sell signal
        else:
            return 0.0  # Hold signal

def run_strategy(strategy: TradingStrategy, historical_data: List[Dict[str, float]]) -> List[float]:
    signals = []
    for data_point in historical_data:
        signal = strategy.execute([data_point])
        signals.append(signal)
    return signals

# Example usage
